// frontend/src/App.js — Phase 2 complete
import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider, useAuth } from './context/AuthContext';
import { PermissionsProvider, usePermissions } from './context/PermissionsContext';
import { GoogleOAuthProvider } from '@react-oauth/google';

// Auth
import LandingPage        from './pages/LandingPage';
import LoginPage          from './pages/auth/LoginPage';
import RegisterPage       from './pages/auth/RegisterPage';
import OTPVerifyPage      from './pages/auth/OTPPage';
import ForgotPasswordPage from './pages/auth/ForgotPasswordPage';
import ResetPasswordPage  from './pages/auth/ResetPasswordPage';

// Core
import DashboardPage      from './pages/dashboard/DashboardPage';
import ProjectsPage       from './pages/projects/ProjectsPage';
import CreateProjectPage  from './pages/projects/CreateProjectPage';
import ProjectDetailPage  from './pages/projects/ProjectDetailPage';
import DailyReportFormPage from './pages/projects/Dailyreportformpage';
import ContractUploadPage from './pages/contracts/ContractUploadPage';
import ContractDetailPage from './pages/contracts/ContractDetailPage';

// Phase 2 — project modules
import PlanningPage       from './pages/projects/PlanningPage';
import BudgetPage         from './pages/projects/BudgetPage';
import QHSEPage           from './pages/projects/QHSEPage';
import PointagePage       from './pages/projects/PointagePage';
import RapportsPage       from './pages/reports/RapportsPage';

// Admin pages
import CompaniesPage      from './pages/admin/CompaniesPage';
import TeamPage           from './pages/admin/TeamPage';
import WorkersPage        from './pages/admin/WorkersPage';
import InventairePage     from './pages/admin/InventairePage';

// ── Spinner ───────────────────────────────────────────────────────────────────
function Spinner() {
  return (
    <div style={{ display:'flex', minHeight:'100vh', alignItems:'center', justifyContent:'center', background:'#0D0D1A' }}>
      <div style={{ width:36, height:36, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite' }}/>
    </div>
  );
}

// ── Route guards ──────────────────────────────────────────────────────────────
function PrivateRoute({ children, module, roles }) {
  const { user, loading } = useAuth();
  const { can, role }     = usePermissions();
  if (loading) return <Spinner/>;
  if (!user)   return <Navigate to="/login" replace/>;
  if (roles && !roles.includes(role)) return <AccessDenied/>;
  if (module && !can(module))          return <AccessDenied/>;
  return children;
}

function PublicRoute({ children }) {
  const { user, loading } = useAuth();
  if (loading) return null;
  return user ? <Navigate to="/dashboard" replace/> : children;
}

function AccessDenied() {
  return (
    <div style={{ display:'flex', minHeight:'100vh', alignItems:'center', justifyContent:'center', background:'#F8F9FA', flexDirection:'column', gap:16 }}>
      <div style={{ fontSize:48 }}>🔒</div>
      <h2 style={{ color:'#1a1f2e', fontSize:22, fontWeight:700, margin:0 }}>Accès restreint</h2>
      <p style={{ color:'#6B7280', fontSize:14, margin:0 }}>Vous n'avez pas les droits pour accéder à cette section.</p>
      <button onClick={()=>window.history.back()} style={{ padding:'10px 24px', borderRadius:8, background:'#fff', border:'1px solid #E5E7EB', color:'#374151', cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>
        ← Retour
      </button>
    </div>
  );
}

function ComingSoon({ title, icon, phase=2 }) {
  return (
    <div style={{ display:'flex', minHeight:'80vh', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:16, background:'#F8F9FA' }}>
      <div style={{ fontSize:56 }}>{icon}</div>
      <h2 style={{ color:'#1a1f2e', fontSize:22, fontWeight:700, margin:0 }}>{title}</h2>
      <p style={{ color:'#6B7280', fontSize:14, margin:0 }}>Ce module sera disponible en Phase {phase}.</p>
      <span style={{ padding:'4px 14px', borderRadius:100, background:'rgba(249,115,22,0.1)', border:'1px solid rgba(249,115,22,0.3)', color:'#F97316', fontSize:12, fontWeight:600 }}>
        En développement
      </span>
    </div>
  );
}

// ── Routes ────────────────────────────────────────────────────────────────────
function AppRoutes() {
  return (
    <Routes>
      {/* Public */}
      <Route path="/"                element={<LandingPage/>}/>
      <Route path="/login"           element={<PublicRoute><LoginPage/></PublicRoute>}/>
      <Route path="/register"        element={<PublicRoute><RegisterPage/></PublicRoute>}/>
      <Route path="/verify-otp"      element={<PublicRoute><OTPVerifyPage/></PublicRoute>}/>
      <Route path="/forgot-password" element={<PublicRoute><ForgotPasswordPage/></PublicRoute>}/>
      <Route path="/reset-password"  element={<PublicRoute><ResetPasswordPage/></PublicRoute>}/>

      {/* Dashboard */}
      <Route path="/dashboard" element={<PrivateRoute><DashboardPage/></PrivateRoute>}/>

      {/* App Owner only */}
      <Route path="/companies"    element={<PrivateRoute roles={['app_owner']}><CompaniesPage/></PrivateRoute>}/>
      <Route path="/users"        element={<PrivateRoute roles={['app_owner']}><ComingSoon title="Tous les utilisateurs" icon="👥"/></PrivateRoute>}/>
      <Route path="/subscriptions"element={<PrivateRoute roles={['app_owner']}><ComingSoon title="Abonnements" icon="💳"/></PrivateRoute>}/>
      <Route path="/monitoring"   element={<PrivateRoute roles={['app_owner']}><ComingSoon title="Monitoring" icon="📡"/></PrivateRoute>}/>
      <Route path="/logs"         element={<PrivateRoute roles={['app_owner']}><ComingSoon title="Logs & Maintenance" icon="🔧"/></PrivateRoute>}/>

      {/* Projects — NOT for App Owner */}
      <Route path="/projects" element={
        <PrivateRoute roles={['admin_entreprise','office_admin','chef_projet','chef_chantier','chef_equipe','ingenieur','qhse','magasinier','comptable','client']}>
          <ProjectsPage/>
        </PrivateRoute>
      }/>
      <Route path="/projects/new" element={
        <PrivateRoute roles={['admin_entreprise','office_admin']}>
          <CreateProjectPage/>
        </PrivateRoute>
      }/>
      <Route path="/projects/:id" element={
        <PrivateRoute roles={['admin_entreprise','office_admin','chef_projet','chef_chantier','chef_equipe','ingenieur','qhse','magasinier','comptable','client']}>
          <ProjectDetailPage/>
        </PrivateRoute>
      }/>

      {/* ── Phase 2: Project-scoped modules ── */}
      {/* Planning / Gantt */}
      <Route path="/projects/:id/planning" element={
        <PrivateRoute module="planning"><PlanningPage/></PrivateRoute>
      }/>
      {/* Budget & Achats */}
      <Route path="/projects/:id/budget" element={
        <PrivateRoute module="budget"><BudgetPage/></PrivateRoute>
      }/>
      {/* QHSE */}
      <Route path="/projects/:id/qhse" element={
        <PrivateRoute module="qhse"><QHSEPage/></PrivateRoute>
      }/>
      {/* Pointage GPS */}
      <Route path="/projects/:id/pointage" element={
        <PrivateRoute roles={['chef_chantier','chef_equipe','admin_entreprise','app_owner']}>
          <PointagePage/>
        </PrivateRoute>
      }/>

      {/* Global planning route (redirects to project selection or top-level view) */}
      <Route path="/planning" element={
        <PrivateRoute module="planning">
          <ComingSoon title="Sélectionnez un projet pour voir son planning" icon="📅"/>
        </PrivateRoute>
      }/>

      {/* Global budget route */}
      <Route path="/budget" element={
        <PrivateRoute module="budget">
          <ComingSoon title="Sélectionnez un projet pour voir son budget" icon="💰"/>
        </PrivateRoute>
      }/>

      {/* Global QHSE route */}
      <Route path="/qhse" element={
        <PrivateRoute module="qhse">
          <ComingSoon title="Sélectionnez un projet pour voir le QHSE" icon="🛡️"/>
        </PrivateRoute>
      }/>

      {/* Pointage global route */}
      <Route path="/pointage" element={
        <PrivateRoute roles={['chef_chantier','chef_equipe','admin_entreprise','app_owner']}>
          <ComingSoon title="Sélectionnez un projet pour pointer" icon="📍"/>
        </PrivateRoute>
      }/>

      {/* Reports — global consolidated */}
      <Route path="/reports" element={
        <PrivateRoute module="reports"><RapportsPage/></PrivateRoute>
      }/>

      {/* Daily reports */}
      <Route path="/projects/:id/reports/new" element={<PrivateRoute module="journal"><DailyReportFormPage/></PrivateRoute>}/>
      <Route path="/projects/:id/reports/:reportId" element={<PrivateRoute module="journal"><DailyReportFormPage/></PrivateRoute>}/>

      {/* Contracts */}
      <Route path="/contracts/upload" element={<PrivateRoute><ContractUploadPage/></PrivateRoute>}/>
      <Route path="/contracts/:id"    element={<PrivateRoute><ContractDetailPage/></PrivateRoute>}/>

      {/* Team & HR */}
      <Route path="/team" element={
        <PrivateRoute roles={['app_owner','admin_entreprise','office_admin','chef_projet']}>
          <TeamPage/>
        </PrivateRoute>
      }/>
      <Route path="/workers" element={
        <PrivateRoute roles={['admin_entreprise','office_admin']}>
          <WorkersPage/>
        </PrivateRoute>
      }/>
      <Route path="/inventory" element={
        <PrivateRoute roles={['admin_entreprise','office_admin']}>
          <InventairePage/>
        </PrivateRoute>
      }/>

      {/* Attendance report */}
      <Route path="/attendance" element={
        <PrivateRoute roles={['office_admin','admin_entreprise']}>
          <ComingSoon title="Rapports de Présence / Paie" icon="📋"/>
        </PrivateRoute>
      }/>

      {/* Other stubs */}
      <Route path="/documents" element={<PrivateRoute module="documents"><ComingSoon title="Documents & Plans" icon="📁"/></PrivateRoute>}/>
      <Route path="/stock"     element={<PrivateRoute module="stock"><ComingSoon title="Stocks & Livraisons" icon="📦"/></PrivateRoute>}/>
      <Route path="/treasury"  element={<PrivateRoute module="treasury"><ComingSoon title="Trésorerie" icon="🏦"/></PrivateRoute>}/>
      <Route path="/settings"  element={<PrivateRoute><ComingSoon title="Paramètres" icon="⚙️"/></PrivateRoute>}/>

      <Route path="*" element={<Navigate to="/dashboard" replace/>}/>
    </Routes>
  );
}

// ── App ───────────────────────────────────────────────────────────────────────
export default function App() {
  const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID || '';
  const app = (
    <AuthProvider>
      <PermissionsProvider>
        <BrowserRouter>
          <Toaster position="top-right" toastOptions={{
            style:{ background:'#1A1A2E', color:'#fff', border:'1px solid rgba(245,158,11,0.2)', fontSize:14 },
            success:{ iconTheme:{ primary:'#10B981', secondary:'#fff' } },
            error:  { iconTheme:{ primary:'#EF4444', secondary:'#fff' } },
          }}/>
          <AppRoutes/>
        </BrowserRouter>
      </PermissionsProvider>
    </AuthProvider>
  );
  return GOOGLE_CLIENT_ID ? <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>{app}</GoogleOAuthProvider> : app;
}
